Etheta = zeros(21,91);Ephi = zeros(21,91);weight_mat = zeros(1,91);weight_max = 1;weight_min = 1;for i = 1:91    weight_mat(1,i) = weight_max - (weight_max-weight_min)*sqrt(abs(i-46)/10);endZ_0 = 50; % Characteristic ImpedanceZ_targ = 50; % Target Input Impedancef = 1e10; % Operating Frequencyw = 2*pi*f;e_0 = 8.8541878188e-12; % Permittivity of Free Spaceu_0 = 4*pi*1e-7; % Permeability of Free Spacek = w*sqrt(u_0*e_0); % WavenumberC_min = 0.14e-12; % Minimum Capacitance (F)X_min = -1 / (w*C_min);C_max = 1.1e-12; % Maximum Capacitance (F)X_max = -1 / (w*C_max);d = 0.00625; % Cell Length (m)for i = 1:21    [theta,phi,numFreqs,Etheta_temp,Ephi_temp,freqs] = loadData("element_patterns/straight_ms_10mm_3-5mm/straight_3-5mm_"+i+".ffd","Phi-Theta");    Etheta(i,:) = Etheta_temp;    Ephi(i,:) = Ephi_temp;endE_rl = zeros(1,91);E_targ = zeros(1,91);for n = 1:21    E_targ = E_targ + exp(1i*(n-1)*k*d.*sind(theta))/21;end% E_targ = 1/21.*(sin(21/2*k*d.*cos(theta))./sin(1/2*k*d.*cos(theta)));I_E = 1;[X_L,Z_LL,Z_LE,Z_EL,Z_EE] = loadMat("straight_ms_zmatrix/UnitCell_Meander_Array_1D_Array_Straight_ZMat_3-5mm_ms.s21p", Z_0, Z_targ, f, 10, 100, 21, 11, 0);x0 = 50*ones(1,10);fun = @(x) radErrorSym(x,E_targ,Etheta,Z_LL,Z_LE,I_E);options = optimoptions(@fmincon, 'Display','iter', MaxFunctionEvaluations=1000000, UseParallel=true);% X_mat = fmincon(fun,x0,[],[],[],[],-1/(w*C_min)*ones(1,20),-1/(w*C_max)*ones(1,20),[],options);X_mat_half = fmincon(fun,x0,[],[],[],[],10*ones(1,10),100*ones(1,10),[],options);X_mat = [X_mat_half, fliplr(X_mat_half)];% C_mat = -1 ./ (w .* X_mat);L_mat = X_mat ./ w;save("mat_files/straight_3-5mm_10mm_sym.mat","L_mat","X_mat","Z_LL","Z_LE","Z_EL","Z_EE","I_E","Etheta","E_targ");% steerAngleIter(0,20,5,"straight_3-5mm_10mm","straight_ms_zmatrix/UnitCell_Meander_Array_1D_Array_Straight_ZMat_3-5mm_ms.s21p",Etheta,theta,0,10,100,I_E,Z_0,21,11,k,d);